--
-- Table structure for table `schedules`
--

DROP TABLE IF EXISTS `schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schedules` (
  `schedule_id` char(12) NOT NULL,
  `office_id` varchar(50) DEFAULT NULL,
  `group_id` varchar(50) DEFAULT NULL,
  `year` smallint DEFAULT NULL,
  `month` tinyint DEFAULT NULL,
  `version` tinyint DEFAULT NULL,
  `created_by` char(12) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `status` varchar(10) NOT NULL DEFAULT 'requested',
  `parameter` json NOT NULL DEFAULT (json_object()),
  `config_id` bigint DEFAULT NULL,
  `violations` json DEFAULT NULL,
  `name` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`schedule_id`),
  UNIQUE KEY `uq_sched_office_group_ymv` (`office_id`,`group_id`,`year`,`month`,`version`),
  KEY `fk_sched_group` (`group_id`),
  KEY `fk_sched_creator` (`created_by`),
  CONSTRAINT `fk_sched_creator` FOREIGN KEY (`created_by`) REFERENCES `nurses` (`account_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sched_group` FOREIGN KEY (`group_id`) REFERENCES `groups` (`group_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_sched_office` FOREIGN KEY (`office_id`) REFERENCES `offices` (`office_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

